fn handle_press_epic(&mut self, _version, rnd, player, data, _debug)
  if !morgard_exists(ctx)  // = spawn_epic: tutorial ∈ {1..6} 이면 false           L503
    return
  on = rnd.gen_range(0..100) < 21                                                   L507
  if !on: return                                                                     L509
  strategy = player.strategy(rnd, game)                                              L510
  team = player.info.team; enemy = 1 - team

  // 공용 서브루틴 (인라인, 소스 L518~547 / L568~606 에 두 벌 복제)
  //   tower(line) = cache.<line>_tower[enemy].or(<line>_tower2[enemy])
  //   has_<line>_first_tower  = tower(line).is_some_and(|t| !t.is_tower2())    // 적 1차 타워 생존
  //   has_<line>_second_tower = tower(line).is_some_and(|t|  t.is_tower2())    // 1차 죽고 2차만 생존
  //   <line>_state = data.blackboard[team].<line>_minion_state.minion_count  (i32 = 그 라인의 내 팀 미니언 수 − 적 미니언 수, BrainMinionParameter::update ai_interface.rs:47 이 씀)
  //   pick(X vs Mid) = if (has_X_first, has_X_second, X_state) > (has_mid_first, has_mid_second, mid_state)  // 튜플 사전식 >
  //                    { X } else { Mid }
  //   emit(kind, line) = self.chats.push(Chat::kind(line, 0)); self.objective = Some(MainObjective::{PressEpic|SplitEpic}(line))
  //   side(champ) = IR 식 `(height - champ.y) <u champ.x`  → true 면 '아래쪽(Bottom 라인) 진영', false 면 '위쪽(Top 라인) 진영'  (인라인 is_top_side = `x <= height−y` 이고 이 IR 식 true = !is_top_side — 17차 배치C 오라클 9/9 + 18차 배치A 오라클 v18A_o1 42,000회 예측 일치로 확정)

  match strategy.morgard_use {                                                       L512
    Gather =>                                                                        L515
      champ = cache.player_champion[team][player.position].unwrap()
      if side(champ)==위쪽:  emit(Press, pick(Top vs Mid))      // L518~530: Top→Press(Top) / else Press(Mid)
      else:                  emit(Press, pick(Bottom vs Mid))   // L535~547: Bottom→Press(Bottom) / else Press(Mid)
      objective = PressEpic(line)

    Split14{position} =>                                                             L552
      epic_tick   = game.get_game_mode().as_moba().unwrap().jungle_runner.epic.next_respawn_tick     L553 (비 Moba → 패닉)
      serpen_tick = ....serpen.next_respawn_tick                                                     L554
      object_far_line = if epic_tick > serpen_tick { Top } else { Bottom }   // 다음에 뜨는 오브젝트에서 먼 라인   L555
      if player.position == position:                                            L561
        emit(Split, object_far_line); objective = SplitEpic(object_far_line)     L562  // 분할 담당자는 먼 라인으로
      else:                                                                      L565
        champ = cache.player_champion[team][player.position].unwrap()
        if side(champ)==위쪽:                                                    L566~584
          if object_far_line == Top: emit(Press, Mid)              L576~577  // Top 이 먼 라인이면 Mid
          else:                      emit(Press, pick(Top vs Mid)) L580~584
        else:                                                                    L590~606
          if object_far_line == Top: emit(Press, pick(Bottom vs Mid))  L598~606
          else:                      emit(Press, Mid)                  L599
        objective = PressEpic(line)

    Split131{position1, position2} =>                                                L613
      if player.position == position1                                                L614
         || (player.position == position2 && cache.player_champion[team][position1].is_none()):   L615
        emit(Split, Top); objective = SplitEpic(Top)                                 L616
      else if player.position == position2:                                          L618
        emit(Split, Bottom); objective = SplitEpic(Bottom)                           L620
      else:
        emit(Press, Mid); objective = PressEpic(Mid)                                 L623
  }                                                                                  L629 ret

  튜플 비교 의미: 1순위 '적 1차 타워가 아직 서 있는 라인'(true>false) → 2순위 '2차 타워만 남은 라인' → 3순위 minion_count(= 그 라인 내 팀 미니언 수 − 적 미니언 수, 부호 있는 i32 차이값) 큰 쪽 — 오라클 v18A_o1 케이스 0/1(top=5·mid=2·bottom=-3 / -1·0·9)로 부호 비교 확인. 즉 덜 밀린(타워가 남은) 사이드 라인을 Mid 보다 우선 압박하고, 동률이면 Mid.

fn v23_enemy_object_pressure(player, data, target) -> bool {
  let ctx = data.context; let game = data.cache.game;
  // 179~192: 대상별 (에픽 id, 위치)
  let (id_opt, pos) = match target {
    Morgard(4) => {                                                    // 181
      if !morgard_exists(ctx)  { return false }   // 인라인: ctx.tutorial ∈ 1..=6 → false  (m15.ll:52567~52569, 극성: (t-1)<u6 → %106 false)
      let moba = game.get_game_mode()[vtable+0x40].as_moba().unwrap(); // 184 — game.rs:231 as_moba; 태그≠0 이면 unwrap_failed(패닉)
      let first = moba.jungle_runner.epic.live_list.first();           // 184 — len(+0x1a8)==0 → None
      (first, ctx.map.camp_pos(Morgard, player.info.team == 0))         // 185 — camp_pos 는 first 가 None 이어도 호출됨(m15.ll:52779~52793 %92 블록: len==0 경로도 camp_pos 호출 뒤 false)
    }
    Serpen(5) => {                                                     // 188
      if !serpen_exists(ctx)   { return false }   // 인라인: ctx.tutorial ∉ {0,5,7,8} → false (m15.ll:52578~52582 switch default → %106)
      let moba = … as_moba().unwrap();                                  // 191
      let first = moba.jungle_runner.serpen.live_list.first();          // 191 — len(+0x1d8)==0 → None
      (first, ctx.map.camp_pos(Serpen, player.info.team == 0))          // 192
    }
    _ => return false                                                  // 179 switch default
  };
  // 197: id → 엔티티
  let Some(ent) = id_opt.and_then(|&id| game.get_entity_by_id(id)[vtable+0x1f0]) else { return false };  // 197 closure$0 = get_entity_by_id 호출부; None(null) → false
  // 200: 보이고 + 피 깎임
  if !game.is_visible(player.info.team, ent.id)[vtable+0xf8] { return false }   // 200 — 먼저 평가(m15.ll:52756~52758)
  if !(ent.hp < ent.stat_cached.hp)               { return false }   // 200 — hp(+0x670) <u stat_cached.hp(+0x628); 풀피면 false (m15.ll:52762~52766)
  // 204~206: 인원 비교
  let allies  = v23_healthy_allies_near_point(player, data, pos.x, pos.y, 180000, 40);        // 204
  let enemies = v23_recent_visible_enemies_near_point(player, data, pos.x, pos.y, 180000, 40); // 205
  enemies != 0 && enemies >= allies                                    // 206 (m15.ll:52774~52776: `%88 ne 0` && `%88 uge %87`)
}

주: camp_pos 반환 {i64,i64} 중 extractvalue 0 → x(%66) 가 3번째 인자, extractvalue 1 → y(%65) 가 4번째 인자로 전달됨(m15.ll:52739~52740, 52770·52772). 둘 다 반환값 range(i64 0,6) 인 i64 카운트.

fn should_keep_object_for_contested_wave_priority(&self, player, data, goal_data, target: WavePriorityObject) -> bool {
  let ctx = data.context;
  // 587~589: 대상 오브젝트가 이 판(튜토리얼 종류)에 존재하는가
  let exists = match target {                                  // 587 (i1 %4 분기 m09.ll:37704)
    Morgard(0) => morgard_exists(ctx),   // 588 — 인라인: !(ctx.tutorial ∈ 1..=6)      (m09.ll:37715~37717)
    Serpen(1)  => serpen_exists(ctx),    // 589 — 인라인: ctx.tutorial ∈ {0,5,7,8}      (m09.ll:37707~37712)
  };
  if !exists { return false }
  // 593: 적이 실제로 치는 중인가
  if !is_object_being_taken_by_enemy(player, data, goal_data, self, target) { return false }   // m09.ll:37720~37721
  // 597~598: 양 팀 건강 인원 셈 (iter_champions = cache.player_champion[team] 5칸 중 Some 만)
  let team = player.info.team;                                  // <2 아니면 panic_bounds_check (m09.ll:37730~37731, 38188)
  let healthy_allies  = iter_champions(team).filter(|e| e.hp*100 / e.stat_cached.hp > 39).count();    // 597 closure$0 — 5칸 언롤(m09.ll:37733~37828); max_hp==0 → div0 패닉
  let healthy_enemies = iter_champions(1-team).filter(|e| e.hp*100 / e.stat_cached.hp > 39).count();  // 598 closure$1 — 5칸 언롤(m09.ll:37829~38180)
  // 600: 판정
  healthy_allies + 1 >= healthy_enemies                          // 600 (m09.ll:38183~38184 `%109+1 uge %195`)
}

극성 근거: %4(target) true → %10 블록의 serpen switch(tutorial 0/5/7/8 → 계속, default → false). false → %11 `(t-1)<u6` 참이면 %16(false). is_object_being_taken_by_enemy false → %16(false).

fn v25_objective_splitter_can_stay(version, player, data, target: JungleType) -> bool {
