  snapshot.current_tick = data.cache.game.tick();      // L619 vtable+0x28
  let range_sq = 6400000000;                           // L622 (80000²)
  let mut targets: bumpalo Vec<&Entity> = Vec::new_in(data.context.pool);   // L627
