   cd  = Entity::skill2_cooltime(self)          // ≥1
   res += dmg * 1000 / cd
}
// L26 return — drop(_t): ENABLED 였으면 PHASE_NANOS[52] += elapsed_ns, PHASE_CALLS[52] += 1 (atomicrmw)
return res

